INSERT INTO reader_changes("entity_key","kind","time","previous_kind","previous_time","operation","payload") SELECT 'message:' || s."id",'transcript',s."time",NULL,NULL,'upsert',json_object('id','message:' || s."id",'kind','transcript','time_ms',s."time",'speaker',s."speaker",'text',s."text",'end_ms',(SELECT "end" FROM transcript_audio WHERE utterance_id=s."id"),'source',COALESCE((SELECT source FROM transcript_audio WHERE utterance_id=s."id"),CASE WHEN s."speaker"='Me' THEN 'microphone' ELSE 'system audio' END),'segment_id',(SELECT id FROM transcript_audio WHERE utterance_id=s."id")) FROM utterances s;
INSERT INTO reader_changes("entity_key","kind","time","previous_kind","previous_time","operation","payload") SELECT 'entry:' || s."id",CASE WHEN s."breakpoint"=1 THEN 'breakpoint' ELSE 'note' END,s."time",NULL,NULL,'upsert',json_object('id','entry:' || s."id",'kind',CASE WHEN s."breakpoint"=1 THEN 'breakpoint' ELSE 'note' END,'time_ms',s."time",'text',s."body",'label',s."label",'message_id',CASE WHEN s."utterance_id" IS NULL THEN NULL ELSE 'message:' || s."utterance_id" END) FROM timeline_entries s;
INSERT INTO reader_changes("entity_key","kind","time","previous_kind","previous_time","operation","payload") SELECT 'span:' || s."id",'span',s."start",NULL,NULL,'upsert',json_object('id','span:' || s."id",'kind','span','time_ms',s."start",'end_ms',s."end",'label',s."label",'text',s."body") FROM notes s;
INSERT INTO reader_changes("entity_key","kind","time","previous_kind","previous_time","operation","payload") SELECT 'comment:' || s."id",'comment',COALESCE((SELECT "time" FROM utterances WHERE id=s."utterance"),0),NULL,NULL,'upsert',json_object('id','comment:' || s."id",'kind','comment','time_ms',COALESCE((SELECT "time" FROM utterances WHERE id=s."utterance"),0),'text',s."body",'message_id','message:' || s."utterance") FROM replies s;
INSERT INTO reader_changes("entity_key","kind","time","previous_kind","previous_time","operation","payload") SELECT 'activity:' || s."event_id",'activity',s."time",NULL,NULL,'upsert',json_object('id','activity:' || s."event_id",'kind','activity','time_ms',s."time",'application',s."application",'action',s."action",'text',COALESCE(json_extract(s."payload",'$.target'), ''),'window',json_extract(s."payload",'$.window'),'url',json_extract(s."payload",'$.url')) FROM activity_events s;
